import { expect, expectStatus, test } from "../../fixtures";

test("Submitting a vendor with all documents extracted puts it in review", { tag: "@REV-01" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorWithDocuments();

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const body = await expectStatus(response, 200);
  expect(body.status).toBe("in_review");
  // Re-read it: the story is about the stored status, not only the response echo.
  const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");
  const audit = await expectStatus<{ items: { action: string }[] }>(await member.get(`/api/vendors/${vendor.id}/audit`), 200);
  expect(audit.items.map((e) => e.action)).toContain("vendor.submitted");
});
